{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "KNI-272, the closest analogue, had absolute oral bioavailability of 36.40% when given as a capsule post-prandially in patients, directly supporting F >= 20% under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "KNI-272 capsule bioavailability ranged from approximately 22% to 55% and was not appreciably different between fasting and post-prandial states, indicating the high threshold is met across feeding conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Atazanavir, a high-transfer HIV protease inhibitor analogue, has oral bioavailability >90% when taken with food, supporting high fed-state bioavailability for this peptidomimetic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Paritaprevir, a peptidomimetic protease inhibitor, had absolute oral bioavailability of 52.6% in healthy volunteers, supporting high bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Esaxerenone showed 90.8% absolute bioavailability in the postprandial state, providing additional evidence that fed-state conditions can support high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A pediatric KNI-272 study with an Ora-Plus suspension reported mean absolute bioavailability of 12% (range 3.5-25%), a low value that is less transferable to the adult fed-capsule condition but represents contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest analogue KNI-272 has absolute oral bioavailability of 36.4% post-prandially and 22-55% overall in adults, and other high-transfer analogues (atazanavir, paritaprevir, esaxerenone) support F >= 20% under fed conditions. The pediatric low value is outweighed by adult fed-state data.",
  "evidence_gaps": [
    "No direct fed-state absolute bioavailability study for the exact query molecule.",
    "Pediatric KNI-272 data (12%) and formulation differences (Ora-Plus suspension) introduce uncertainty.",
    "Food effect for the query itself is not directly measured; inferred from close analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

